SELECT BILL_ID AS "billId", BILL_NO AS "billNo", BILL_DATE AS "billDate", BILL_TIME AS "billTime", VIP_CODE AS "vipCode", VIP_MOBILE AS "vipMobile", OMS_SOURCECODE AS "omsSourcecode", SALES_TYPE AS "salesType", ITEM_ID AS "itemId", BILL_POS_ID AS "billPosId", BILL_POS_CODE AS "billPosCode", BILL_POS_NAME AS "billPosName", STORE_ID AS "storeId", STORE_CODE AS "storeCode", STORE_NAME AS "storeName", PRODUCT_CODE AS "productCode", PRODUCT_STYLE_NO AS "productStyleNo", PRODUCT_NAME AS "productName", COLORSALIAS AS "colorsalias", BARCODE AS "barcode", SIZES AS "sizes", QTY AS "qty", RETAIL_PRICE AS "retailPrice", RETAIL_AMOUNT AS "retailAmount", TRANSACTION_AMOUNT AS "transactionAmount", TOT_AMT_ACTUAL AS "totAmtActual", AMT_RECEIVABLE AS "amtReceivable", REVENUE AS "revenue", RECALC_REVENUE AS "recalcRevenue", NEW_OLD_NAME_ADJUST AS "newOldNameAdjust", ANCHOR_SUMMARYID AS "anchorSummaryid", ANCHOR_SUMMARYNAME AS "anchorSummaryname", PROMOTION_NAME AS "promotionName" FROM ODS_SALES_MAIN
AND BILL_NO = #{q.billNo}
AND BILL_TIME >= #{q.billTimeStart}
AND BILL_TIME < #{q.billTimeEnd} + 1
ORDER BY BILL_TIME DESC, BILL_NO DESC
